with source as (
    select * from {{ source('ripple_raw', 'INTL_IPC_FOOD_INSECURITY_GLOBAL') }}
)

select
    try_to_date(DATE_OF_ANALYSIS) as date_of_analysis,
    COUNTRY as country,
    try_to_double(TOTAL_COUNTRY_POPULATION) as total_country_population,
    VALIDITY_PERIOD as validity_period,
    C_FROM as c_from,
    C_TO as c_to,
    PHASE as phase,
    NUMBER as number,
    try_to_double(PERCENTAGE) as percentage
from source
